from collections import deque

def bfs_dist(grid, start_cells, grid_rows, grid_cols):
    """Compute distance from start_cells to each 1-cell"""
    dist = {cell: float('inf') for r in range(grid_rows) for c in range(grid_cols) if grid[r][c] == 1}

    if not start_cells:
        return dist

    q = deque(start_cells)
    for cell in start_cells:
        dist[cell] = 0

    while q:
        cr, cc = q.popleft()
        for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
            nr, nc = cr + dr, cc + dc
            if 0 <= nr < grid_rows and 0 <= nc < grid_cols and grid[nr][nc] == 1 and (nr, nc) not in dist:
                if dist.get((nr, nc), float('inf')) == float('inf'):
                    dist[(nr, nc)] = dist[(cr, cc)] + 1
                    q.append((nr, nc))

    return dist

